	// neither a claimable invite nor a domain match is rejected. Identity-scoped.
	// Gated on brent:write.
	JoinWorkspace(context.Context, *connect.Request[sdp_go.JoinWorkspaceRequest]) (*connect.Response[sdp_go.JoinWorkspaceResponse], error)
