	// verified bindings. Refused when it would remove the last active admin. The
	// caller must be an active admin of workspace_id. Gated on brent:write.
	RemoveWorkspaceMember(context.Context, *connect.Request[sdp_go.RemoveWorkspaceMemberRequest]) (*connect.Response[sdp_go.RemoveWorkspaceMemberResponse], error)
	// Promotes or demotes a workspace member between admin and member. When the
	// member is a pending invite, the backing invitation role is updated too.
	// Refused when a demotion would leave zero active admins. The caller must be
	// an active admin of workspace_id. Gated on brent:write.
	UpdateWorkspaceMemberRole(context.Context, *connect.Request[sdp_go.UpdateWorkspaceMemberRoleRequest]) (*connect.Response[sdp_go.UpdateWorkspaceMemberRoleResponse], error)
