	// Deletes the workspace's LLM provider key. Idempotent: deleting a missing key
	// succeeds. Workspace-scoped and admin-only. Gated on brent:write.
	DeleteWorkspaceLLMCredential(context.Context, *connect.Request[sdp_go.DeleteWorkspaceLLMCredentialRequest]) (*connect.Response[sdp_go.DeleteWorkspaceLLMCredentialResponse], error)
	// Returns metadata for the calling principal's personal Cursor API key in
	// the header workspace. Never returns the secret or Cursor account email.
	// Workspace-scoped; gated on brent:read.
	GetMyCursorCredentialStatus(context.Context, *connect.Request[sdp_go.GetMyCursorCredentialStatusRequest]) (*connect.Response[sdp_go.GetMyCursorCredentialStatusResponse], error)
	// Validates and stores the calling principal's personal Cursor user API key.
	// Service-account keys and keys bound to another principal are rejected.
	// Workspace-scoped; gated on brent:write.
	SetMyCursorCredential(context.Context, *connect.Request[sdp_go.SetMyCursorCredentialRequest]) (*connect.Response[sdp_go.SetMyCursorCredentialResponse], error)
	// Deletes the calling principal's personal Cursor key and tombstones its
	// verified Cursor binding. Idempotent and workspace-scoped; gated on brent:write.
	DeleteMyCursorCredential(context.Context, *connect.Request[sdp_go.DeleteMyCursorCredentialRequest]) (*connect.Response[sdp_go.DeleteMyCursorCredentialResponse], error)
	// Returns the workspace's configured git integration role and the Manage URL
	// for the connected git provider.
	// Workspace-scoped; the caller must be an active member. Gated on brent:read.
	GetWorkspaceIntegrationRoles(context.Context, *connect.Request[sdp_go.GetWorkspaceIntegrationRolesRequest]) (*connect.Response[sdp_go.GetWorkspaceIntegrationRolesResponse], error)
	// Sets the workspace's integration roles. Validates that providers are
	// eligible for their roles via the app-level registry. When git_provider
	// changes away from a connected provider, disconnects the previous git
	// install. Workspace-scoped and admin-only. Gated on brent:write.
	SetWorkspaceIntegrationRoles(context.Context, *connect.Request[sdp_go.SetWorkspaceIntegrationRolesRequest]) (*connect.Response[sdp_go.SetWorkspaceIntegrationRolesResponse], error)
	// Re-sends the account verification email to the signed-in caller by minting
	// an Auth0 email-verification ticket and delivering it via Resend. Powers the
	// "Verify your email" interstitial. The caller is resolved from the JWT.
	//
	// Idempotent by design: when the caller's email is already verified the call
