	// webhook credentials (shown once at connect). Gated on brent:read.
	GetGitLabConnection(context.Context, *connect.Request[sdp_go.GetGitLabConnectionRequest]) (*connect.Response[sdp_go.GetGitLabConnectionResponse], error)
	// Validates a GitLab access token against the customer's instance, persists
