	// Gated on brent:write.
	ConnectGitLab(context.Context, *connect.Request[sdp_go.ConnectGitLabRequest]) (*connect.Response[sdp_go.ConnectGitLabResponse], error)
	// Stores the GitLab webhook signing token (whsec_...) the customer generated
	// in GitLab, enabling HMAC-SHA256 (Standard Webhooks) verification of inbound
	// deliveries in addition to the plain-text webhook secret. Optional, run
	// after ConnectGitLab and after the customer creates the webhook in GitLab.
	// Gated on brent:write.
	SaveGitLabSigningToken(context.Context, *connect.Request[sdp_go.SaveGitLabSigningTokenRequest]) (*connect.Response[sdp_go.SaveGitLabSigningTokenResponse], error)
	// Idempotently upserts a `principal_bindings` row of `state='verified'` for
