	ListIntegrationCatalogue(context.Context, *connect.Request[sdp_go.ListIntegrationCatalogueRequest]) (*connect.Response[sdp_go.ListIntegrationCatalogueResponse], error)
	// Creates a new workspace from a display name and provisions the caller as
