	DiscoverLoginRecoveryCandidates(context.Context, *connect.Request[sdp_go.DiscoverLoginRecoveryCandidatesRequest]) (*connect.Response[sdp_go.DiscoverLoginRecoveryCandidatesResponse], error)
	// Renames the workspace named by the Brent-Workspace-Id header: edits
