	UpdateWorkspaceBranding(context.Context, *connect.Request[sdp_go.UpdateWorkspaceBrandingRequest]) (*connect.Response[sdp_go.UpdateWorkspaceBrandingResponse], error)
	// Marks the given workspace's onboarding as complete, flipping
