	CompleteWorkspaceOnboarding(context.Context, *connect.Request[sdp_go.CompleteWorkspaceOnboardingRequest]) (*connect.Response[sdp_go.CompleteWorkspaceOnboardingResponse], error)
	// Soft-deletes a workspace the caller actively administers. Identity-scoped:
