	ListJoinableWorkspaces(context.Context, *connect.Request[sdp_go.ListJoinableWorkspacesRequest]) (*connect.Response[sdp_go.ListJoinableWorkspacesResponse], error)
	// Joins the calling identity to a workspace it is eligible for. The server
