	AddApprovedEmailDomain(context.Context, *connect.Request[sdp_go.AddApprovedEmailDomainRequest]) (*connect.Response[sdp_go.AddApprovedEmailDomainResponse], error)
	// Verifies an approved email domain by its emailed code, flipping it to
	// verified on success. Wrong/expired codes are rejected; the attempt cap and a
