	// Workspace-scoped and admin-only. Gated on brent:write.
	ResendApprovedEmailDomainCode(context.Context, *connect.Request[sdp_go.ResendApprovedEmailDomainCodeRequest]) (*connect.Response[sdp_go.ResendApprovedEmailDomainCodeResponse], error)
	// Deletes an approved email domain (verified or not) from the header
	// workspace. Workspace-scoped and admin-only. Gated on brent:write.
	DeleteApprovedEmailDomain(context.Context, *connect.Request[sdp_go.DeleteApprovedEmailDomainRequest]) (*connect.Response[sdp_go.DeleteApprovedEmailDomainResponse], error)
	// Returns display metadata (connected flag, last-4 chars, timestamps) for the
	// workspace's stored LLM provider key. Never returns the secret itself. The
	// caller must be an active member of the header workspace. Gated on brent:read.
	GetWorkspaceLLMCredentialStatus(context.Context, *connect.Request[sdp_go.GetWorkspaceLLMCredentialStatusRequest]) (*connect.Response[sdp_go.GetWorkspaceLLMCredentialStatusResponse], error)
	// Sets (or replaces) the workspace's LLM provider key. The secret is validated
	// against the provider API before storage; an auth failure rejects the call,
	// while a transient probe error stores the key with a warning and a null
