	GetMyCursorCredentialStatus(context.Context, *connect.Request[sdp_go.GetMyCursorCredentialStatusRequest]) (*connect.Response[sdp_go.GetMyCursorCredentialStatusResponse], error)
	// Validates and stores the calling principal's personal Cursor user API key.
	// Service-account keys and keys bound to another principal are rejected.
	// Workspace-scoped; gated on brent:write.
	SetMyCursorCredential(context.Context, *connect.Request[sdp_go.SetMyCursorCredentialRequest]) (*connect.Response[sdp_go.SetMyCursorCredentialResponse], error)
	// Deletes the calling principal's personal Cursor key and tombstones its
